const item=$input.first(); const f=item.json; const binary=item.binary||{};
const testOnly=String(f.mode||'').startsWith('Uji koneksi');
const selection=String(f.slides||'Otomatis sesuai isi transkrip');
const count=selection.startsWith('Otomatis')?0:Number(selection);
const reuse=String(f.source||'').startsWith('Gunakan transkrip');
const jobId=reuse?String(f.job_id||'').trim():'';
const outputMode=String(f.output_mode||'Ringkasan Word + PPT').includes('saja')?'summary_only':'summary_ppt';
const key=Object.keys(binary)[0];let inputError='';
if(!testOnly&&!reuse&&!key)inputError='Pilih satu file rekaman atau transkrip terlebih dahulu.';
if(!testOnly&&reuse&&!/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/.test(jobId))inputError='ID pekerjaan tersimpan tidak valid.';
if(![0,4,6,8,10,12,16].includes(count))inputError='Jumlah slide tidak sesuai pilihan yang tersedia.';
if(!testOnly&&!reuse&&key&&!/\.(mp3|wav|m4a|mp4|webm|ogg|flac|txt)$/i.test(binary[key].fileName||''))inputError='Gunakan audio yang didukung atau TXT UTF-8.';
return [{json:{title:String(f.title||'Ringkasan diskusi').slice(0,180),slide_count:String(count),output_mode:outputMode,reuse_job_id:jobId,testOnly,inputError},binary,pairedItem:{item:0}}];

const prepared=$('Siapkan kiriman').first(); const health=$input.first().json;
const connected=health.ok===true;let reason=prepared.json.inputError;
if(!connected)reason='Aplikasi pemrosesan lokal belum terhubung. Jalankan Mulai.cmd pada folder proyek Documents/Codex, lalu coba lagi.';
else if(!health.api_key_configured)reason='API key belum terbaca di aplikasi lokal. Simpan konfigurasi lalu muat ulang konfigurasi.';
else if((health.quality_pipeline_version||0)<2)reason='Pemeriksaan otomatis versi baru belum aktif. Mulai ulang aplikasi lokal dari folder Documents/Codex, lalu buka form ini lagi.';
else if(health.summary_docx_supported!==true)reason='Format ringkasan Word belum aktif. Mulai ulang aplikasi lokal, lalu buka form lagi.';
else if(health.planning_supported!==true)reason='Rekomendasi dan Action Plan belum aktif. Mulai ulang aplikasi lokal.';
else if((health.transcription_api_version||0)<1||health.transcription_provider!=='openai')reason='GPT-Transcribe belum aktif. Mulai ulang layanan aplikasi dan pastikan TRANSCRIPTION_PROVIDER=openai.';
else if(health.speaker_audio_supported!==true)reason='Versi transkripsi dengan pembicara belum aktif. Mulai ulang layanan aplikasi.';
else if(health.output_modes_supported!==true)reason='Pilihan keluaran belum aktif; mulai ulang aplikasi lokal.';
else if(prepared.json.output_mode!=='summary_only'&&prepared.json.slide_count==='0'&&health.auto_slide_count_supported!==true)reason='Mode Otomatis memerlukan aplikasi lokal versi terbaru. Mulai ulang layanan aplikasi, lalu buka form ini lagi. Jumlah manual masih dapat dipilih.';
const notes=['Aplikasi lokal: '+(connected?'terhubung':'belum terhubung'), 'API key: '+(health.api_key_configured?'terisi':'belum terisi'), 'Pemeriksaan otomatis: '+((health.quality_pipeline_version||0)>=2?'aktif':'perlu memulai ulang aplikasi lokal'), 'Ringkasan Word: '+(health.summary_docx_supported===true?'aktif':'perlu memulai ulang aplikasi lokal'), 'Rekomendasi dan Action Plan: '+(health.planning_supported===true?'aktif':'perlu memulai ulang aplikasi'), 'Transkripsi: '+String(health.transcription_model||'versi lama')+'; audio dikirim ke OpenAI dan berbayar', 'Model ringkasan: '+String(health.model||'belum tersedia'), 'Jumlah otomatis: '+(health.auto_slide_count_supported===true?'aktif':'perlu memulai ulang aplikasi lokal'), 'Uji ini tidak mengirim permintaan AI berbayar. Akses model dan kualitas hasil belum diuji lewat API.'];
return [{json:{...prepared.json,ready:!reason,info:prepared.json.testOnly?notes.join('\n'):reason},binary:prepared.binary,pairedItem:{item:0}}];

function statusPage(job) {
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const valid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(job.id||'');
 const terminal=['completed','needs_review','failed','interrupted'].includes(job.status);
 const pending=valid&&!terminal;
 const labels={completed:job.recovery_method==='editorial_saved_transcript'?'Hasil dipulihkan — siap diunduh':'Hasil siap diunduh',needs_review:'Draf: masih ada bagian belum pasti',failed:'Proses perlu diperbaiki',interrupted:'Proses terhenti',running:'Sedang diproses',queued:'Dalam antrean',waiting:'Menunggu tahap berikutnya'};
 const links=[['transcript-client.html','Transkrip mudah dibaca'],['transcript-client.txt','Transkrip mudah dibaca TXT'],['transcript.txt','Transkrip asli'],['transcript-checked.txt','Transkrip bertanda'],['quality.md','Catatan kualitas'],['summary.docx','Ringkasan Word'],['presentation.pptx','PowerPoint'],['action-plan.xlsx','Action Plan Excel'],['plan-notes.md','Catatan rencana'],['review.json','Catatan pemeriksaan']].filter(([file])=>(job.files||[]).includes(file)).map(([file,label])=>`<a target="_blank" rel="noopener noreferrer" href="http://127.0.0.1:8765/api/jobs/${encodeURIComponent(job.id)}/files/${file}">${label}</a>`).join('');
 const title=valid?(labels[job.status]||'Sedang diproses'):'Pekerjaan tidak ditemukan';
 const body=`<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hasil diskusi</title><style>body{font:17px Arial,sans-serif;background:#101b24;color:#f4f0e8;max-width:800px;margin:60px auto;padding:0 24px;line-height:1.6}h1{font-size:34px}a{display:inline-block;color:#fff;background:#89532e;padding:10px 18px;margin:10px 10px 10px 0;border-radius:5px;text-decoration:none}progress{width:100%;height:15px;accent-color:#b77545}.muted{color:#b0b8bb}section{margin-top:24px}</style></head><body><p class="muted">OTOMASI DISKUSI MELALUI N8N</p><h1>${esc(title)}</h1><p>${esc(valid?job.title:'Periksa kembali tautan hasil pekerjaan.')}</p><p>${esc(valid?job.message:'')}</p>${pending?`<progress max="100" value="${Math.max(0,Math.min(100,Number(job.progress)||0))}"></progress><p class="muted">Halaman diperbarui setiap 10 detik. Biarkan komputer dan layanan lokal tetap berjalan.</p>`:''}${job.status==='needs_review'?'<p>Buka Catatan kualitas untuk melihat temuan spesifik. Hasil ini belum lolos seluruh pemeriksaan otomatis.</p>':''}<section>${links}</section><p class="muted">Pemeriksaan AI menilai kesesuaian dengan transkrip. Ucapan yang tidak jelas tetap dapat memerlukan konfirmasi audio.</p>${valid&&job.usage?`<p class="muted">Estimasi API yang tercatat: US$${esc(job.usage.estimated_usd)}. Tagihan aktual mengikuti dashboard OpenAI.</p>`:''}<p class="muted">Nomor pekerjaan: ${esc(valid?job.id:'â€”')}</p><a target="_top" href="http://localhost:5678/form/diskusi-unggah">Unggah rekaman lain</a><a target="_blank" rel="noopener noreferrer" href="http://localhost:5678/workflow/diskusiLocalWorkflow">Lihat workflow utama</a></body></html>`;
 return {html:body,pending};
}
return $input.all().map(item=>({json:statusPage(item.json)}));
